// Clean, composable game objects
var player = new GameObject("Player")
    .AddComponent<Transform>()
    .AddComponent<SpriteRenderer>()
    .AddComponent<PlayerController>()
    .AddComponent<Collider2D>();

public class GameScene : Scene
{
    protected override void Initialize()
    {
        // Declarative scene setup
        CreateEntity("Player")
            .With<Transform>(position: new Vector2(100, 100))
            .With<PlayerController>(speed: 200f);

        CreateEntity("Background")
            .With<SpriteRenderer>(sprite: "background.png");
    }
}

public class PlayerController : Component
{
    protected override void Update()
    {
        var movement = Input.GetVector("move");
        Transform.Position += movement * speed * Time.DeltaTime;

        if (Input.JustPressed("jump"))
            Jump();
    }
}

// Create a new project
// File > New > Turian Game Project

using Turian;

public class MyFirstGame : Game
{
    protected override void Initialize()
    {
        LoadScene<MainScene>();
    }
}

public class MainScene : Scene
{
    protected override void Initialize()
    {
        CreateEntity("Hello World")
            .With<Transform>()
            .With<TextRenderer>(text: "Hello, Turian!");
    }
}
